const input = $input.first().json;
const headers = input.headers || {};
const secret = $vars.LEADFLOW_WEBHOOK_SECRET;
if (!secret || headers['x-leadflow-secret'] !== secret) throw new Error('Unauthorized LeadFlow webhook. Configure LEADFLOW_WEBHOOK_SECRET in n8n Variables and use the same value in Supabase secrets.');
const event = input.body || input;
const p = event.payload || {};
const lead = p.lead || {};
const phone = String(lead.phone || '').replace(/[\s().-]/g, '');
if (!/^\+[1-9]\d{7,14}$/.test(phone)) throw new Error('Lead has no valid international phone number. Store phone as +countrycode number.');
let body = '';
if (event.event === 'lead.created') body = 'Hello ' + (lead.name || 'there') + ', thank you for contacting Legal Wegal. We have received your enquiry and our team will follow up with you shortly.';
else if (event.event === 'payment.confirmed') body = 'Hello ' + (lead.name || 'there') + ', we have received your payment of ₹' + Number(p.amount || 0).toLocaleString('en-IN') + '. Thank you. Your remaining balance is ₹' + Number(p.pendingPaymentAfter || 0).toLocaleString('en-IN') + '.';
else if (event.event === 'payment.reminder_due') body = 'Hello ' + (lead.name || 'there') + ', this is a reminder that ₹' + Number(p.pendingAmount || 0).toLocaleString('en-IN') + ' is pending for your Legal Wegal service. Please contact our team if you have already paid.';
else throw new Error('Unsupported LeadFlow event: ' + event.event);
return [{json:{to:'whatsapp:'+phone,body,event:event.event,eventId:event.eventId || ''}}];
